namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 500, 9_500)]
    [InlineData(LoyaltyTier.Silver, 1_000, 9_000)]
    [InlineData(LoyaltyTier.Gold, 1_500, 8_500)]
    public void S1_MemberReceivesApprovedDiscountOnCartSubtotal(
        LoyaltyTier loyaltyTier,
        int expectedDiscountCents,
        int expectedTotalCents)
    {
        var useCase = new CalculateLoyaltyDiscount();

        var quote = useCase.Handle(new CalculateLoyaltyDiscountQuery(10_000, loyaltyTier));

        Assert.Equal(
            new LoyaltyDiscountQuote(10_000, expectedDiscountCents, expectedTotalCents, loyaltyTier),
            quote);
    }

    // S2 - The loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_000, 18_000)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_000, 28_000)]
    [InlineData(12_000, LoyaltyTier.Gold, 1_800, 10_200)]
    public void S2_LoyaltyDiscountNeverExceedsTwentyEuros(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents) =>
        AssertQuote(subtotalCents, tier, null, discountCents, totalCents);

    // S3 - No loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData(2_999, 0, 2_999)]
    [InlineData(3_000, 450, 2_550)]
    public void S3_NoLoyaltyDiscountUnderThirtyEuros(int subtotalCents, int discountCents, int totalCents) =>
        AssertQuote(subtotalCents, LoyaltyTier.Gold, null, discountCents, totalCents);

    // S9 - Platinum members receive a 20 % loyalty discount
    [Theory]
    [InlineData(10_000, 2_000, 8_000)]
    [InlineData(5_000, 1_000, 4_000)]
    [InlineData(20_000, 2_000, 18_000)]
    public void S9_PlatinumMembersReceiveTwentyPercent(int subtotalCents, int discountCents, int totalCents) =>
        AssertQuote(subtotalCents, LoyaltyTier.Platinum, null, discountCents, totalCents);

    // S10 - The discount never exceeds the subtotal
    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_DiscountNeverExceedsTheSubtotal(int subtotalCents, LoyaltyTier tier, int discountCents) =>
        AssertQuote(subtotalCents, tier, "WELCOME5", discountCents, 0);

    internal static void AssertQuote(int subtotalCents, LoyaltyTier tier, string? promoCode, int discountCents, int totalCents) =>
        Assert.Equal(
            new LoyaltyDiscountQuote(subtotalCents, discountCents, totalCents, tier),
            new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier, promoCode)));
}

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class PromoCodeAcceptanceTests
{
    // S4 - The WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_500, 8_500)]
    [InlineData(2_000, LoyaltyTier.Bronze, 500, 1_500)]
    public void S4_WelcomeFiveTakesFiveEurosAfterTheLoyaltyDiscount(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents) =>
        CalculateLoyaltyDiscountAcceptanceTests.AssertQuote(subtotalCents, tier, "WELCOME5", discountCents, totalCents);

    // S5 - The cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData(20_000, LoyaltyTier.Gold, 2_500, 17_500)]
    [InlineData(30_000, LoyaltyTier.Silver, 2_500, 27_500)]
    public void S5_CapAppliesToTheLoyaltyDiscountOnly(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents) =>
        CalculateLoyaltyDiscountAcceptanceTests.AssertQuote(subtotalCents, tier, "WELCOME5", discountCents, totalCents);

    // S6 - Promo codes ignore case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodesIgnoreCase(string code) =>
        Assert.Equal(
            1_500,
            new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10_000, LoyaltyTier.Silver, code)).DiscountCents);

    // S7 - The SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, 1_900, 8_100)]
    [InlineData(30_000, LoyaltyTier.Bronze, 3_000, 27_000)]
    [InlineData(2_000, LoyaltyTier.Gold, 200, 1_800)]
    public void S7_SummerTenTakesTenPercentOfWhatIsLeft(int subtotalCents, LoyaltyTier tier, int discountCents, int totalCents) =>
        CalculateLoyaltyDiscountAcceptanceTests.AssertQuote(subtotalCents, tier, "SUMMER10", discountCents, totalCents);

    // S8 - An unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored() =>
        CalculateLoyaltyDiscountAcceptanceTests.AssertQuote(10_000, LoyaltyTier.Silver, "SPRING", 1_000, 9_000);
}

namespace CheckoutPricing.UnitTest.Shipping;

public sealed class ShippingFeeAcceptanceTests
{
    // S11 - Standard shipping is free from 50.00 EUR payable
    [Theory]
    [InlineData(4_999, LoyaltyTier.Bronze, 490)]
    [InlineData(5_000, LoyaltyTier.Bronze, 0)]
    [InlineData(4_999, LoyaltyTier.Silver, 490)]
    public void S11_StandardShippingIsFreeFromFiftyEuros(int payableCents, LoyaltyTier tier, int feeCents) =>
        Assert.Equal(feeCents, new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payableCents, tier)));

    // S12 - Gold and Platinum members never pay standard shipping
    [Theory]
    [InlineData(LoyaltyTier.Gold)]
    [InlineData(LoyaltyTier.Platinum)]
    public void S12_GoldAndPlatinumNeverPayStandardShipping(LoyaltyTier tier) =>
        Assert.Equal(0, new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(1_000, tier)));

    // S13 - Express shipping costs 9.90 EUR, free for Platinum members only
    [Theory]
    [InlineData(10_000, LoyaltyTier.Bronze, 990)]
    [InlineData(1_000, LoyaltyTier.Gold, 990)]
    [InlineData(1_000, LoyaltyTier.Platinum, 0)]
    public void S13_ExpressShippingCostsNineNinety(int payableCents, LoyaltyTier tier, int feeCents) =>
        Assert.Equal(feeCents, new CalculateShippingFee().Handle(new CalculateShippingFeeQuery(payableCents, tier, Express: true)));
}

namespace CheckoutPricing.UnitTest.Checkout;

public sealed class QuoteCheckoutAcceptanceTests
{
    // S14 - The checkout quote adds shipping to the payable total
    [Theory]
    [InlineData(10_000, LoyaltyTier.Silver, "WELCOME5", false, 8_500, 0, 8_500)]
    [InlineData(5_000, LoyaltyTier.Bronze, null, false, 4_750, 490, 5_240)]
    [InlineData(20_000, LoyaltyTier.Platinum, "SUMMER10", true, 16_500, 0, 16_500)]
    [InlineData(2_000, LoyaltyTier.Gold, null, true, 2_000, 990, 2_990)]
    public void S14_CheckoutQuoteAddsShippingToThePayableTotal(
        int subtotalCents, LoyaltyTier tier, string? promoCode, bool express, int payableCents, int shippingCents, int totalCents) =>
        Assert.Equal(
            new CheckoutQuote(payableCents, shippingCents, totalCents),
            new QuoteCheckout().Handle(new QuoteCheckoutQuery(subtotalCents, tier, promoCode, express)));
}
